    enRows:[["helfen","to help"],["geben","to give"],["schenken","to give as a gift"],["danken","to thank"],["gehören","to belong to"],["zeigen","to show"],["erklären","to explain"],["antworten","to answer"],["gratulieren","to congratulate"],["empfehlen","to recommend"]],
    note:"Questi verbi vogliono l'oggetto al dativo, non all'accusativo.",
    enNote:"These verbs take a dative object, not an accusative one.",
    ex:[["Ich helfe dir.","Ti aiuto (a te)."]],
